function FonHen_JieMa(u) {
    var a = u.split("*");
    var b = '';
    for (var i = 1, n = a.length; i < n; i++) {
        b += String.fromCharCode(a[i])
    }
    return b
}
let match = src.match(/var now=FonHen_JieMa\("(.*)"\);var pn/);
if (match) {
    result = FonHen_JieMa(match[1]);
}
